11-plates-which-point", "text": "Определите, в какой из обозначенных на карте цифрами точек на границе литосферных плит происходит процесс раздвижение плит с земной корой материкового типа.", "answer": "3", "accepted": null, "short": "Точка 3 — Восточно-Африканский рифт (Эфиопия, Афар). Здесь материковая плита раскалывается и её части расходятся — образуется рифт: глубокие впадины, озёра, вулканы.", "alg": "1. Определи, где лежит каждая точка: срединный хребет в океане, побережье с желобом, высокие горы внутри материка или рифт.\n2. Сопоставь каждую точку с процессом.\n3. Запиши номер точки, где идёт названный процесс.", "mistakes": "Островные дуги и глубоководные желоба образуются там, где океаническая плита погружается под другую; столкновение материковых плит даёт высокие горы (Гималаи), а не желоба.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": "https://dcaclbmeuzrnsapkhkuf.supabase.co/storage/v1/object/public/question-images/VPR7/gen2027/b5-m05.webp", "topic": "2.4.1", "topics2": ["2.4.11"], "batch": "b5", "meta_extra": null}, {"key": "t11-m05-ccb", "task": 11, "type": "input_number", "template": "vpr7-11-plates-which-point", "text": "Определите, в какой из обозначенных на карте цифрами точек на границе литосферных плит происходит процесс столкновение плит с земной корой материкового типа.", "answer": "4", "accepted": null, "short": "Точка 4 — Гиндукуш и Памир. Здесь сталкиваются плиты с материковой корой: кора сминается в складки и поднимаются высокие горы.", "alg": "1. Определи, где лежит каждая точка: срединный хребет в океане, побережье с желобом, высокие горы внутри материка или рифт.\n2. Сопоставь каждую точку с процессом.\n3. Запиши номер точки, где идёт названный процесс.", "mistakes": "Островные дуги и глубоководные желоба образуются там, где океаническая плита погружается под другую; столкновение материковых плит даёт высокие горы (Гималаи), а не желоба.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": "https://dcaclbmeuzrnsapkhkuf.supabase.co/storage/v1/object/public/question-images/VPR7/gen2027/b5-m05.webp", "topic": "2.4.1", "topics2": ["2.4.11"], "batch": "b5", "meta_extra": null}]$json$::jsonb) as x(
  key text, task int, type text, template text, text text, answer text, accepted jsonb, short text, alg text,
  mistakes text, difficulty int, kind text, rubric text, max_score int, image text, topic text, topics2 jsonb, batch text, meta_extra jsonb)
loop
  select id into qid from public.questions where meta->>'gen_key' = r.key;
  if qid is null then
    insert into public.questions (subject, assessment, task_no, type, text, difficulty, status, image_url, source, source_year,
        grade_min, grade_max, meta, short_explanation, solution_algorithm, typical_mistakes, template_id)
    values ('geo', 'vpr7', r.task, r.type::public.question_type, r.text, r.difficulty, 'draft', r.image, 'GeoFAQ: авторские задания по формату ВПР 2027', 2027, 7, 7,
        jsonb_build_object('set', 'vpr7-gen2027', 'batch', r.batch, 'gen_key', r.key, 'author', 'geofaq', 'format', 'vpr2027')
          || coalesce(r.meta_extra, '{}'::jsonb),
        r.short, r.alg, r.mistakes, (select id from public.task_templates where code = r.template))
    returning id into qid;
    insert into public.answers (question_id, kind, answer_text, accepted_variants, max_score, rubric_text)
    values (qid, r.kind::public.answer_kind, r.answer, r.accepted, r.max_score, r.rubric);
  elsif (select status from public.questions where id = qid) = 'draft' then
    update public.questions set text = r.text, type = r.type::public.question_type, difficulty = r.difficulty,
        image_url = r.image, meta = meta || coalesce(r.meta_extra, '{}'::jsonb), short_explanation = r.short, solution_algorithm = r.alg, typical_mistakes = r.mistakes,
        updated_at = now() where id = qid;
    update public.answers set kind = r.kind::public.answer_kind, answer_text = r.answer, accepted_variants = r.accepted,
        max_score = r.max_score, rubric_text = r.rubric, updated_at = now() where question_id = qid;
  end if;
  delete from public.question_topics where question_id = qid;
  insert into public.question_topics (question_id, topic_id, is_primary)
    select qid, id, true from public.topics where code = r.topic and subject = 'geo';
  insert into public.question_topics (question_id, topic_id, is_primary)
    select qid, t.id, false from public.topics t where t.subject = 'geo'
      and t.code in (select jsonb_array_elements_text(coalesce(r.topics2, '[]'::jsonb))) and t.code <> r.topic;
end loop;
end $$;
